try {
  const input = $input.first().json || {};
  const event = input.event;
  const eventId = input.eventId;
  const occurredAt = input.occurredAt;

  if (!event || typeof event !== 'string') {
    throw new Error('Required field "body.event" is missing or invalid.');
  }

  // The COMPLETE original event payload - never reduced to the normalised fields.
  let metadata = input.metadata;
  if (typeof metadata === 'string') {
    try {
      metadata = JSON.parse(metadata);
    } catch (e) {
      metadata = null;
    }
  }  
  const executionId = $execution.id;

  // foiRequestMetaData arrives as an object (intake events) or as a JSON string (IAO / ministry events).
  let foiRequestMetaData = metadata.foiRequestMetaData;
  if (typeof foiRequestMetaData === 'string') {
    try {
      foiRequestMetaData = JSON.parse(foiRequestMetaData);
    } catch (e) {
      foiRequestMetaData = null;
    }
  }
  let metadataString = "";
  if (!metadata || typeof metadata === 'string') {   
      metadataString = metadata;    
  } else if (!metadata || typeof metadata === 'object') {
      metadataString = JSON.stringify(metadata);
    }
  const IAO_COMPLETE_EVENTS = ['foi-iao-open-complete', 'foi-iao-complete', 'foi-iao-reopen'];
  if (IAO_COMPLETE_EVENTS.includes(event)) {
    const first = (...values) => {
      for (const v of values) { if (v !== undefined && v !== null && v !== '') return v; }
      return null;
    };

    return {
      json: {
        event,
        eventId,
        occurredAt,
        rawRequestId: first(foiRequestMetaData.rawRequestId),
        foiRequestId: first(foiRequestMetaData.foiRequestID, foiRequestMetaData.foiRequestId),
        ministryRequestId: first(foiRequestMetaData.ministryRequestID, foiRequestMetaData.ministryRequestId),
        status: foiRequestMetaData.status,
        assignedTo: foiRequestMetaData.assignedTo,
        assignedGroup: foiRequestMetaData.assignedGroup,
        fileNumber: foiRequestMetaData?.id,
        previousStatus: foiRequestMetaData?.previousstatus,
        isPaymentActive: foiRequestMetaData?.isPaymentActive,
        isSync: foiRequestMetaData?.issync,
        isOfflinePayment: foiRequestMetaData?.isofflinepayment,
        paymentExpiryDate: foiRequestMetaData?.paymentExpiryDate,
        metadata: metadataString,
        executionId,
      },
    };
  }

} catch (error) {
   const input = $input.first().json || {};
  return {
    json: {
      event: '',
      eventId: (input && typeof input === 'object' && typeof input.eventId === 'string') ? input.eventId : null,
      receivedEvent: (input && typeof input === 'object' && typeof input.event === 'string') ? input.event : null,
      error: true,
      errorMessage: error.message,
      metadata: input.metadata ?? null,
      executionId: $execution.id,
    },
  };
}

// Same inputs the previous 'IAO Complete: Trigger Fee Payment' node sent (category foi-fee-payment, NOT PAID).
try {
  const input = $('Set Event Variables').first().json || {};
  return [{
    json: {
      ...input,
      event: 'foi-fee-payment',
      feeAction: 'initiate',
      triggeredBy: input.event,
      category: 'foi-fee-payment',
      paymentStatus: 'NOT PAID',
      isSync: input.isSync,
      isOfflinePayment: input.isOfflinePayment,
      isPaymentActive: input.isPaymentActive,
      rawRequestId: input.rawRequestId,
      foiRequestId: input.foiRequestId,
      ministryRequestId: input.ministryRequestId,
      fileNumber: input.fileNumber,
      paymentExpiryDate: input.paymentExpiryDate,
      previousStatus: input.previousStatus
    }
  }];
  } catch (error) {
   const input = $('Set Event Variables').first().json || {};
    return {
      json: {
        event: '',
        receivedEvent: (input && typeof input === 'object' && typeof input.event === 'string') ? input.event : null,
        error: true,
        errorMessage: error.message,
        metadata: input.metadata ?? null,
        executionId: $execution.id,
      },
    };
}

const eventVariables = $('Set Event Variables').first().json;
const sla = $input.first().json || {};
return [{ 
  json: { 
    ...eventVariables, 
    feeflow: sla.sla_status === 'ACTIVE' ? 'ONGOING' : 'NA', 
    paymentSlaId: sla.id ?? null, 
    paymentUrl: sla.payment_url ?? '', 
    slaPaymentExpiryDate: sla.payment_expiry_date ?? '' 
  } 
}];

// Replaces 'Update Instance: Payment Status' + 'Parse Payment Data' + 'Cancel Payment' (HTTP resume of the fee Wait).
try {
  const input = $('Set Fee Flow').first().json || {};
  const saveDataPayload = JSON.stringify({ paymenturl: input.paymentUrl, paymentexpirydate: input.slaPaymentExpiryDate || input.paymentExpiryDate })
  return [{
    json: {
      ...input,
      event: 'foi-manage-payment',
      feeAction: 'cancel',
      triggeredBy: input.event,
      category: 'foi-manage-payment',
      paymentStatus: 'CANCELLED',
      isSync: input.isSync,
      isOfflinePayment: input.isOfflinePayment,
      isPaymentActive: input.isPaymentActive,
      rawRequestId: input.rawRequestId,
      foiRequestId: input.foiRequestId,
      ministryRequestId: input.ministryRequestId,
      fileNumber: input.fileNumber,
      paymentExpiryDate: input.paymentExpiryDate,
      previousStatus: input.previousStatus,
      saveDataPayload: saveDataPayload
    }
  }];
  } catch (error) {
   const input = $('Set Fee Flow').first().json || {};
    return {
      json: {
        event: '',
        receivedEvent: (input && typeof input === 'object' && typeof input.event === 'string') ? input.event : null,
        error: true,
        errorMessage: error.message,
        metadata: input.metadata ?? null,
        executionId: $execution.id,
      },
    };
}
